BEGIN;
SELECT setval(pg_get_serial_sequence('users','id'), COALESCE((SELECT MAX(id) FROM users), 1), TRUE);
SELECT setval(pg_get_serial_sequence('interests','id'), COALESCE((SELECT MAX(id) FROM interests), 1), TRUE);
SELECT setval(pg_get_serial_sequence('communities','id'), COALESCE((SELECT MAX(id) FROM communities), 1), TRUE);
SELECT setval(pg_get_serial_sequence('posts','id'), COALESCE((SELECT MAX(id) FROM posts), 1), TRUE);
SELECT setval(pg_get_serial_sequence('comments','id'), COALESCE((SELECT MAX(id) FROM comments), 1), TRUE);
SELECT setval(pg_get_serial_sequence('friend_requests','id'), COALESCE((SELECT MAX(id) FROM friend_requests), 1), TRUE);
SELECT setval(pg_get_serial_sequence('conversations','id'), COALESCE((SELECT MAX(id) FROM conversations), 1), TRUE);
SELECT setval(pg_get_serial_sequence('messages','id'), COALESCE((SELECT MAX(id) FROM messages), 1), TRUE);
